function openReconJob(id){
  const j=(reconnaissanceJobs||[]).find(x=>x.id===id);if(!j)return;
  document.getElementById('recon-job-title').textContent=`${j.id} · ${j.profile}`;
  const results=j.results||[];
  const resultCards=results.map(x=>{
    const services=(x.services||[]).map(s=>`<tr><td>${esc(s.port)}</td><td>${esc(s.transport||'tcp')}</td><td>${esc(s.service||'unknown')}</td><td>${esc(s.product||s.banner||'—')}</td><td>${esc(s.version||'—')}</td></tr>`).join('');
    const audit=(x.audit||[]).map(a=>`<tr><td>${time(a.observed_at)}</td><td><code>${esc(a.stage)}</code></td><td><span class="sensor-state sensor-state-${esc(a.status)}">${esc(a.status)}</span></td><td>${esc(a.detail||'—')}</td></tr>`).join('');
    const evidence=(x.evidence||[]).map(e=>`<tr><td>${esc(e.field)}</td><td>${esc(e.value)}</td><td>${esc(e.source)}</td><td>${esc(e.confidence)}%</td></tr>`).join('');
    const changes=(x.changes||[]).map(c=>`<tr><td><span class="pill severity-${esc(c.severity||'info')}">${esc(c.kind)}</span></td><td>${esc(c.field)}</td><td>${esc(c.previous||'—')}</td><td>${esc(c.current||'—')}</td></tr>`).join('');
    return `<section class="panel"><h3>${esc(x.target)} · ${x.reachable?'reachable':'not reached'}</h3><div class="identity-grid">${[['Hostname',x.hostname||'—'],['Vendor',x.vendor||'—'],['Model',x.model||'—'],['OS',x.os||'—'],['Firmware',x.firmware||'—'],['Error',x.error||'—']].map(v=>`<div><span>${v[0]}</span><strong>${esc(v[1])}</strong></div>`).join('')}</div><h4>Changes since previous discovery</h4><div class="scrollable"><table class="data-table"><thead><tr><th>Change</th><th>Field</th><th>Previous</th><th>Current</th></tr></thead><tbody>${changes||'<tr><td colspan="4">No changes detected</td></tr>'}</tbody></table></div><h4>Pipeline audit</h4><div class="scrollable"><table class="data-table"><thead><tr><th>Time</th><th>Stage</th><th>Status</th><th>Detail</th></tr></thead><tbody>${audit||'<tr><td colspan="4">No audit data (legacy result)</td></tr>'}</tbody></table></div><h4>Services</h4><div class="scrollable"><table class="data-table"><thead><tr><th>Port</th><th>Transport</th><th>Service</th><th>Product / banner</th><th>Version</th></tr></thead><tbody>${services||'<tr><td colspan="5">No open configured ports</td></tr>'}</tbody></table></div><h4>Evidence</h4><div class="scrollable"><table class="data-table"><thead><tr><th>Field</th><th>Value</th><th>Source</th><th>Confidence</th></tr></thead><tbody>${evidence||'<tr><td colspan="4">No evidence collected</td></tr>'}</tbody></table></div></section>`;
  }).join('');
  document.getElementById('recon-job-body').innerHTML=`<div class="identity-grid">${[['Sensor',j.sensor_id],['Status',j.status],['Created',time(j.created_at)],['Started',j.started_at?time(j.started_at):'—'],['Completed',j.completed_at?time(j.completed_at):'—'],['Targets',(j.targets||[]).length],['Rate',`${j.policy?.packets_per_second||'—'} probes/s`],['Timeout',`${j.policy?.timeout_seconds||'—'} s`]].map(x=>`<div><span>${x[0]}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div><h3>Discovery debug</h3>${resultCards||'<div class="empty-state">No result uploaded yet. Check that the sensor is online and polling Central commands.</div>'}`;
  document.getElementById('recon-job-modal').hidden=false;
}
