function assetRecon(a){return {hostname:a.ReconHostname||a.Hostname||'',vendor:a.ReconVendor||a.Vendor||'',os:a.ReconOS||'',model:a.ReconModel||'',firmware:a.ReconFirmware||'',serial:a.ReconSerial||'',services:a.ReconServices||[],evidence:a.ReconEvidence||[],ot:a.ReconOTIdentity||{},last:a.LastProfiledAt||''}}
function assetRelatedAlerts(a){return (alerts||[]).filter(x=>{const raw=JSON.stringify(x);return (!a.SensorID||raw.includes(a.SensorID))&&((a.IP&&raw.includes(a.IP))||(a.MAC&&raw.toLowerCase().includes(String(a.MAC).toLowerCase())))}).sort((x,y)=>new Date(y.LastSeen??y.last_seen??0)-new Date(x.LastSeen??x.last_seen??0))}
function assetRisk(a){const related=assetRelatedAlerts(a),critical=related.some(x=>String(x.Severity??x.severity).toLowerCase()==='critical'),high=related.some(x=>['high','critical'].includes(String(x.Severity??x.severity).toLowerCase())),stale=a.IdentityActive===false,unknown=!(a.Hostname||a.ReconHostname)||!(a.Vendor||a.ReconVendor);return critical?['Critical','critical']:high?['High','high']:stale?['Stale','medium']:unknown?['Needs profiling','medium']:['Low','low']}
