    try{const history=await api(`/sensors/${encodeURIComponent(sensorID)}/assets/${encodeURIComponent(ip)}/recon-history`);if(activeAssetDetail?.SensorID!==sensorID||activeAssetDetail?.IP!==ip)return;const rows=Array.isArray(history)?history:[];body.innerHTML=`<div class="scrollable"><table class="data-table"><thead><tr><th>Time</th><th>Hostname</th><th>Vendor / model</th><th>OS / firmware</th><th>Changes</th></tr></thead><tbody>${rows.map(h=>{const x=h.result||{},changes=h.changes||[];return `<tr><td>${time(h.observed_at)}</td><td>${esc(x.hostname||'—')}</td><td>${esc([x.vendor,x.model].filter(Boolean).join(' / ')||'—')}</td><td>${esc([x.os,x.firmware].filter(Boolean).join(' / ')||'—')}</td><td>${changes.map(c=>`<span class="pill severity-${esc(c.severity||'info')}" title="${esc((c.previous||'—')+' → '+(c.current||'—'))}">${esc(c.kind)} ${esc(c.field)}</span>`).join(' ')||'No change'}</td></tr>`}).join('')||'<tr><td colspan="5">No profiling history</td></tr>'}</tbody></table></div>`}catch(err){body.innerHTML=`<div class="empty-dashboard">Failed to load reconnaissance history: ${esc(err.message)}</div>`}
