document.getElementById('asset-detail-close').onclick=()=>document.getElementById('asset-detail-modal').hidden=true;document.querySelector('.asset-detail-tabs').onclick=e=>{const b=e.target.closest('[data-asset-panel]');if(b)renderAssetPanel(b.dataset.assetPanel)};document.getElementById('asset-detail-body').addEventListener('click',e=>{const b=e.target.closest('[data-asset-action]');if(!b)return;if(b.dataset.assetAction==='discover')document.getElementById('asset-run-discovery').click();else if(b.dataset.assetAction==='alerts'){document.getElementById('asset-detail-modal').hidden=true;openDashboardTab('alerts')}else if(b.dataset.assetAction==='lifecycle')renderAssetPanel('lifecycle')});
async function waitForReconJob(jobID,button){for(let i=0;i<90;i++){await new Promise(r=>setTimeout(r,2000));await loadRecon();const j=(reconnaissanceJobs||[]).find(x=>x.id===jobID);if(!j)continue;button.textContent=j.status==='queued'?'Waiting for sensor…':j.status==='running'?'Discovering…':'Refreshing asset…';if(['completed','partially_completed','failed'].includes(j.status)){await refreshAll();const fresh=(assets||[]).find(x=>x.SensorID===activeAssetDetail?.SensorID&&x.IP===activeAssetDetail?.IP);if(fresh){activeAssetDetail=fresh;renderAssetPanel('identity')}button.disabled=false;button.textContent=j.status==='failed'?'Discovery failed':'Run safe discovery';return}}button.disabled=false;button.textContent='Run safe discovery';alert('Discovery is still waiting for the sensor. Check sensor connectivity and the Reconnaissance jobs view.')}
document.getElementById('asset-run-discovery').onclick=async()=>{if(!activeAssetDetail)return;const button=document.getElementById('asset-run-discovery'),existing=(reconnaissanceJobs||[]).find(j=>j.sensor_id===activeAssetDetail.SensorID&&(j.targets||[]).includes(activeAssetDetail.IP)&&['queued','running'].includes(j.status));if(existing){button.disabled=true;button.textContent=existing.status==='running'?'Discovering…':'Waiting for sensor…';waitForReconJob(existing.id,button);return}button.disabled=true;button.textContent='Queueing…';try{const profile=(activeAssetDetail.IsOT||activeAssetDetail.Category==='OT')?'ot-conservative':'safe-discovery';const job=await queueRecon(activeAssetDetail.SensorID,[activeAssetDetail.IP],profile,{standalone:true});button.textContent='Waiting for sensor…';waitForReconJob(job.id,button)}catch(e){button.disabled=false;button.textContent='Run safe discovery';alert(e.parsed?.error||e.message)}};


document.getElementById('recon-credential-form')?.addEventListener('submit',async e=>{e.preventDefault();const st=document.getElementById('recon-cred-status');try{await api('/reconnaissance/credentials',{method:'POST',body:JSON.stringify({name:document.getElementById('recon-cred-name').value,type:'ssh',username:document.getElementById('recon-cred-user').value,password:document.getElementById('recon-cred-password').value,private_key:document.getElementById('recon-cred-key').value})});e.target.reset();st.textContent='Credential stored';await loadRecon()}catch(err){st.textContent=err.parsed?.error||err.message}});
document.getElementById('table-recon-credentials')?.addEventListener('click',async e=>{const b=e.target.closest('.recon-cred-delete');if(!b)return;if(!confirm('Delete this credential?'))return;try{await api('/reconnaissance/credentials/'+encodeURIComponent(b.dataset.id),{method:'DELETE'});await loadRecon()}catch(err){alert(err.parsed?.error||err.message)}});

// Task-oriented sidebar navigation. Group state is local UI preference only.
const NAV_SECTIONS={dashboard:'Overview',topology:'Network & architecture',purdue:'Network & architecture',segmentation:'Network & architecture',assets:'Assets & inventory',devices:'Assets & inventory',tags:'Assets & inventory',vulnerabilities:'Assets & inventory',reconnaissance:'Assets & inventory',alerts:'Detection & response',nba:'Detection & response',incidents:'Detection & response',rules:'Detection & response',threatintel:'Detection & response',dns:'Investigation',smb:'Investigation',analysis:'Investigation',reports:'Investigation',sensors:'Operations',health:'Operations',data:'Operations',users:'Administration',settings:'Administration',audit:'Administration'};
function updateNavigationContext(tab,button){
  document.getElementById('current-section').textContent=NAV_SECTIONS[tab]||'OTLens';
  document.getElementById('current-page').textContent=(button?.textContent||TAB_LABELS[tab]||tab).trim().replace(/\s+\d+$/,'');
  const group=button?.closest('.nav-group');
  if(group&&!group.classList.contains('open')){group.classList.add('open');group.querySelector('.nav-group-toggle')?.setAttribute('aria-expanded','true')}
  try{localStorage.setItem('otlens.lastTab',tab)}catch(_){ }
  document.body.classList.remove('sidebar-open');
}
function refreshNavigationGroups(){
  const query=(document.getElementById('nav-filter')?.value||'').trim().toLowerCase();let any=false;
  document.querySelectorAll('.nav-group').forEach(group=>{
    let visible=0;group.querySelectorAll('.tab').forEach(tab=>{const allowed=!tab.hidden,match=!query||tab.textContent.toLowerCase().includes(query);tab.classList.toggle('nav-filter-hidden',!(allowed&&match));if(allowed&&match)visible++});
    group.classList.toggle('nav-filter-hidden',visible===0);if(query&&visible){group.classList.add('open');group.querySelector('.nav-group-toggle')?.setAttribute('aria-expanded','true')}if(visible)any=true;
  });
  const home=document.querySelector('.nav-home');if(home){const show=!home.hidden&&(!query||home.textContent.toLowerCase().includes(query));home.classList.toggle('nav-filter-hidden',!show);if(show)any=true}
  const empty=document.getElementById('nav-empty');if(empty)empty.hidden=any;
}
document.querySelector('.tabs')?.addEventListener('click',e=>{
  const toggle=e.target.closest('.nav-group-toggle');if(toggle){const group=toggle.closest('.nav-group'),open=group.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));try{localStorage.setItem(`otlens.nav.${group.dataset.navGroup}`,open?'1':'0')}catch(_){ }return}
  const tab=e.target.closest('.tab');if(tab)updateNavigationContext(tab.dataset.tab,tab);
});
document.querySelectorAll('.nav-group').forEach(group=>{try{const saved=localStorage.getItem(`otlens.nav.${group.dataset.navGroup}`);if(saved!==null){group.classList.toggle('open',saved==='1');group.querySelector('.nav-group-toggle')?.setAttribute('aria-expanded',String(saved==='1'))}}catch(_){}});
document.getElementById('nav-filter')?.addEventListener('input',refreshNavigationGroups);
document.getElementById('sidebar-toggle')?.addEventListener('click',()=>document.body.classList.toggle('sidebar-open'));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('sidebar-open');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('nav-filter')?.focus()}});

function downloadTextFile(name,text,type='text/csv'){
  const blob=new Blob([text],{type:`${type};charset=utf-8`}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),0);
}
document.getElementById('devices-template')?.addEventListener('click',()=>downloadTextFile('otlens-assets-template.csv','mac,category,name\n00:11:22:33:44:55,PLC/RTU,PLC-Line-1\n'));
document.getElementById('tags-template')?.addEventListener('click',()=>downloadTextFile('otlens-tags-template.csv','device_ip,device_port,protocol,address_space,address,name,operation\n10.20.1.10,502,Modbus,holding_register,120,Tank level,read\n'));

// Restore the last page after authentication when the role still permits it.
window.addEventListener('load',()=>{setTimeout(()=>{refreshNavigationGroups();const active=document.querySelector('.tab.active');if(active)updateNavigationContext(active.dataset.tab,active)},0)});

function detailGrid(obj){return `<dl class="detail-grid">${Object.entries(obj||{}).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v,null,2):v??'—')}</dd>`).join('')}</dl>`}
// Rule-row details are owned by app-detection.js so the Rules table and detail modal stay in one UI flow.
document.querySelector('#table-smb tbody')?.addEventListener('click',e=>{const row=e.target.closest('.smb-detail-row');if(!row)return;const x=smbObservations[Number(row.dataset.index)];if(x){document.getElementById('smb-detail-body').innerHTML=detailGrid(x);document.getElementById('smb-detail-modal').hidden=false}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-close-modal]');if(b)document.getElementById(b.dataset.closeModal).hidden=true});
document.getElementById('vuln-template-download')?.addEventListener('click',()=>{const csv='cve_id,vendor,product,severity,title,published_date,url\nCVE-2026-0001,Example Vendor,Example Product,high,Example vulnerability,2026-01-15,https://example.invalid/advisory/CVE-2026-0001\n';const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='otlens-vulnerability-template.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(a.href)});
document.getElementById('vuln-import-submit')?.addEventListener('click',async()=>{const input=document.getElementById('vuln-import-file');if(!input.files?.length){alert('Select a vulnerability CSV file first.');return}const fd=new FormData();fd.append('file',input.files[0]);try{const r=await api('/vulnerabilities/import',{method:'POST',body:fd});alert(`Imported ${r.accepted} advisories; ${r.rejected} rejected; queued for ${r.queued_sensors} sensors.`);input.value='';await refreshAll()}catch(err){alert(err.parsed?.error||err.message)}});

document.getElementById('vuln-feed-refresh')?.addEventListener('click',async()=>{const name=document.getElementById('vuln-feed-name').value.trim(),url=document.getElementById('vuln-feed-url').value.trim();if(!url){alert('Enter a vulnerability feed URL.');return}try{const r=await api('/vulnerabilities/feed',{method:'POST',body:JSON.stringify({name,url})});alert(`Loaded ${r.accepted} advisories; ${r.rejected} rejected; queued for ${r.queued_sensors} sensors.`);await refreshAll()}catch(err){alert(err.parsed?.error||err.message)}});


document.getElementById('audit-filter-apply')?.addEventListener('click',loadAuditFiltered);
document.getElementById('audit-filter-clear')?.addEventListener('click',()=>{['audit-filter-actor','audit-filter-action','audit-filter-sensor'].forEach(id=>document.getElementById(id).value='');document.getElementById('audit-filter-result').value='';loadAuditFiltered()});
document.getElementById('download-diagnostics')?.addEventListener('click',downloadDiagnostics);


function populateSensorSelect(el,multiple=false){if(!el)return;const current=multiple?Array.from(el.selectedOptions).map(x=>x.value):el.value;el.innerHTML=(multiple?'':'<option value="">Select sensor</option>')+sensors.map(x=>`<option value="${esc(x.ID||x.id)}">${esc(x.Name||x.name||x.ID||x.id)}</option>`).join('');if(multiple){Array.from(el.options).forEach(o=>o.selected=current.includes(o.value))}else el.value=current}
async function openAssetContexts(){const modal=document.getElementById('asset-context-modal');modal.hidden=false;populateSensorSelect(document.getElementById('asset-context-sensor'));await loadAssetContexts()}
async function loadAssetContexts(){const sensor=document.getElementById('asset-context-sensor')?.value||'';try{assetContextsData=await api('/asset-context'+(sensor?'?sensor_id='+encodeURIComponent(sensor):''));renderAssetContexts()}catch(e){alert(e.parsed?.error||e.message)}}
function renderAssetContexts(){const body=document.querySelector('#table-asset-context tbody');if(!body)return;body.innerHTML=(assetContextsData||[]).map((x,i)=>`<tr><td>${esc(x.sensor_id)}</td><td>${esc(x.asset_ip)}</td><td>${esc(x.asset_role||'—')}</td><td>${esc(x.criticality||'—')}</td><td>${esc(x.zone||'—')}</td><td>${esc(x.purdue_override??'auto')}</td><td>${x.is_attack_path_entry?'yes':'no'}</td><td>${x.is_attack_path_target?'yes':'no'}</td><td>${time(x.updated_at)}</td><td><button class="secondary-btn asset-context-edit" data-index="${i}" ${can('data_management')?'':'disabled'}>Edit</button></td></tr>`).join('')||'<tr><td colspan="10">No context overrides.</td></tr>'}
async function editContextFromRegistry(x){const role=prompt('Asset role:',x.asset_role||'');if(role===null)return;const criticality=prompt('Criticality (low, medium, high, critical):',x.criticality||'medium');if(criticality===null)return;const zone=prompt('Zone:',x.zone||'');if(zone===null)return;const purdue=prompt('Purdue override (blank = automatic):',x.purdue_override??'');if(purdue===null)return;const entry=confirm('Mark as attack-path entry point?');const target=confirm('Mark as attack-path target?');await api(`/sensors/${encodeURIComponent(x.sensor_id)}/assets/${encodeURIComponent(x.asset_ip)}/context`,{method:'PUT',body:JSON.stringify({asset_role:role,criticality,zone,purdue_override:purdue===''?null:Number(purdue),is_attack_path_entry:entry,is_attack_path_target:target})});await loadAssetContexts();await refreshAll()}
function renderContactGraph(incident){const graph=document.getElementById('malware-trace-graph');const ex=incident?.exposures||[];const byHop={};ex.forEach(x=>(byHop[x.hop_count]??=[]).push(x));const levels=[[{asset_ip:incident.initial_asset_ip,exposure_severity:incident.severity||'critical'}],...Object.keys(byHop).sort((a,b)=>a-b).map(k=>byHop[k])];graph.innerHTML=levels.map((level,i)=>`${i?'<span class="contact-arrow">→</span>':''}<div>${level.map(x=>`<div class="contact-node"><strong>${esc(x.asset_ip)}</strong><small>${esc(x.exposure_severity||'initial')} · hop ${i}</small></div>`).join('')}</div>`).join('')}
function showMalwareTrace(incident){document.getElementById('malware-trace-summary').textContent=`Incident #${incident.id}: ${incident.title||'Contact trace'} · ${incident.exposures?.length||0} exposed assets · ${incident.lookback_hours}h lookback`;renderContactGraph(incident);document.querySelector('#table-malware-exposures tbody').innerHTML=(incident.exposures||[]).map(x=>`<tr><td>${esc(x.asset_ip)}</td><td>${esc(x.parent_asset_ip||'—')}</td><td>${esc(x.hop_count)}</td><td>${esc(x.exposure_score)}</td><td><span class="severity ${esc(x.exposure_severity)}">${esc(x.exposure_severity)}</span></td><td>${esc((x.protocols||[]).join(', ')||'—')}</td><td>${esc(x.packets||0)} pkts / ${esc(x.bytes||0)} B</td><td>${time(x.first_contact)} → ${time(x.last_contact)}</td><td>${esc((x.reasons||[]).join('; ')||'—')}</td></tr>`).join('')||'<tr><td colspan="9">No exposed assets found.</td></tr>'}
function openMalwareTrace(){document.getElementById('malware-trace-modal').hidden=false;populateSensorSelect(document.getElementById('malware-trace-sensor'));const selectedAsset=assets.find(a=>selected.has(`${a.SensorID}|${a.MAC}`))||activeAssetDetail;if(selectedAsset){document.getElementById('malware-trace-sensor').value=selectedAsset.SensorID;document.getElementById('malware-trace-ip').value=selectedAsset.IP||''}}
function openRuleSetModal(){const modal=document.getElementById('ruleset-modal');modal.hidden=false;document.getElementById('ruleset-error').textContent='';populateSensorSelect(document.getElementById('ruleset-assign-sensors'),true);const list=document.getElementById('ruleset-rule-list');list.innerHTML=rules.map((r,i)=>{const custom=String(r.Kind).toLowerCase()==='custom';return `<label class="ruleset-rule-option"><input type="checkbox" value="${i}" checked><span><strong>${esc(r.Name)}</strong><small>${esc(r.SensorID)} · ${custom?'custom':'built-in'} · ${esc(r.Severity||'—')}</small></span></label>`}).join('')||'<p class="rules-help">No rules available. Create a custom rule first or wait for built-ins to synchronize from a sensor.</p>'}
function normalizedRule(r){const copy={...r};['SensorID','HitCount','LastHit','SimulationHits','LastSimulationHit'].forEach(k=>delete copy[k]);return copy}

document.getElementById('asset-context-open')?.addEventListener('click',openAssetContexts);
document.getElementById('asset-context-sensor')?.addEventListener('change',loadAssetContexts);
document.querySelector('#table-asset-context tbody')?.addEventListener('click',e=>{const b=e.target.closest('.asset-context-edit');if(b)editContextFromRegistry(assetContextsData[Number(b.dataset.index)]).catch(err=>alert(err.parsed?.error||err.message))});
document.getElementById('malware-trace-open')?.addEventListener('click',openMalwareTrace);
document.getElementById('malware-trace-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const incident=await api('/malware-incidents/contact-trace',{method:'POST',body:JSON.stringify({sensor_id:document.getElementById('malware-trace-sensor').value,asset_ip:document.getElementById('malware-trace-ip').value.trim(),lookback_hours:Number(document.getElementById('malware-trace-lookback').value),max_hops:Number(document.getElementById('malware-trace-hops').value)})});const detail=await api('/malware-incidents/'+encodeURIComponent(incident.id));showMalwareTrace(detail)}catch(err){alert(err.parsed?.error||err.message)}});
document.getElementById('ruleset-create-open')?.addEventListener('click',openRuleSetModal);
document.getElementById('ruleset-form')?.addEventListener('submit',async e=>{e.preventDefault();const chosen=Array.from(document.querySelectorAll('#ruleset-rule-list input:checked')).map(x=>normalizedRule(rules[Number(x.value)])).filter(Boolean);if(!chosen.length){document.getElementById('ruleset-error').textContent='Select at least one rule.';return}const rs={id:document.getElementById('ruleset-id').value.trim(),name:document.getElementById('ruleset-name').value.trim(),version:Number(document.getElementById('ruleset-version').value),rules:chosen};try{lastCreatedRuleSet=await api('/rulesets',{method:'POST',body:JSON.stringify(rs)});const sensorIDs=Array.from(document.getElementById('ruleset-assign-sensors').selectedOptions).map(x=>x.value);await Promise.all(sensorIDs.map(id=>api(`/sensors/${encodeURIComponent(id)}/ruleset/${encodeURIComponent(rs.id)}`,{method:'PUT'})));document.getElementById('ruleset-last-result').textContent=`Created ${lastCreatedRuleSet.name||rs.name} v${lastCreatedRuleSet.version||rs.version} with ${chosen.length} rules; assigned to ${sensorIDs.length} sensors.`;document.getElementById('ruleset-modal').hidden=true}catch(err){document.getElementById('ruleset-error').textContent=err.parsed?.error||err.message}});
